import React, { useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../App';

const features = [
  { icon: '🌱', title: 'AI Crop Recommendation', desc: 'Get personalized crop suggestions based on soil, weather & market trends.' },
  { icon: '🔬', title: 'Disease Detection', desc: 'Upload a photo and our AI instantly identifies crop diseases with 95% accuracy.' },
  { icon: '🌦️', title: 'Smart Weather Alerts', desc: 'Hyperlocal weather forecasts and smart irrigation scheduling.' },
  { icon: '💰', title: 'Profit Prediction', desc: 'AI-powered market analysis to maximize your harvest income.' },
  { icon: '🤖', title: 'KisanGPT Chatbot', desc: 'Ask anything in your language — Hindi, Marathi, Punjabi & more.' },
  { icon: '📍', title: 'GPS Field Mapping', desc: 'Map your fields, track soil zones and monitor crop health remotely.' },
];

const stats = [
  { value: '2.4L+', label: 'Farmers Empowered' },
  { value: '95%', label: 'Disease Accuracy' },
  { value: '₹18K', label: 'Avg Income Boost' },
  { value: '12+', label: 'Languages Supported' },
];

export default function LandingPage() {
  const navigate = useNavigate();
  const { lang, LANG_LIST } = useAuth();
  const canvasRef = useRef(null);
  const currentLang = LANG_LIST?.find(l => l.code === lang);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    const particles = Array.from({ length: 60 }, () => ({
      x: Math.random() * canvas.width, y: Math.random() * canvas.height,
      r: Math.random() * 2 + 0.5, vx: (Math.random() - 0.5) * 0.4, vy: (Math.random() - 0.5) * 0.4,
      alpha: Math.random() * 0.5 + 0.1,
    }));
    let raf;
    const draw = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      particles.forEach(p => {
        p.x += p.vx; p.y += p.vy;
        if (p.x < 0 || p.x > canvas.width) p.vx *= -1;
        if (p.y < 0 || p.y > canvas.height) p.vy *= -1;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(34,197,94,${p.alpha})`;
        ctx.fill();
      });
      // Draw connections
      particles.forEach((a, i) => particles.slice(i + 1).forEach(b => {
        const d = Math.hypot(a.x - b.x, a.y - b.y);
        if (d < 120) {
          ctx.beginPath();
          ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y);
          ctx.strokeStyle = `rgba(34,197,94,${0.08 * (1 - d / 120)})`;
          ctx.lineWidth = 0.5;
          ctx.stroke();
        }
      }));
      raf = requestAnimationFrame(draw);
    };
    draw();
    const resize = () => { canvas.width = window.innerWidth; canvas.height = window.innerHeight; };
    window.addEventListener('resize', resize);
    return () => { cancelAnimationFrame(raf); window.removeEventListener('resize', resize); };
  }, []);

